<div class="d-flex justify-content-between align-items-center mb-3"><h1>Cadastro de clientes</h1><a class="btn btn-primary" href="/?r=clientes&form=1">Novo cliente</a></div><form class="row g-2 mb-3"><input type="hidden" name="r" value="clientes"><div class="col-md-9"><input class="form-control" name="q" placeholder="Buscar por nome, CPF ou e-mail" value="<?=htmlspecialchars($_GET['q']??'')?>"></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Buscar</button></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Nome</th><th>CPF</th><th>E-mail</th><th>Telefone</th><th>Ações</th></tr></thead><tbody><?php foreach($clientes as $c): ?><tr><td><?=htmlspecialchars($c['nome'])?></td><td><?=htmlspecialchars($c['cpf']??'')?></td><td><?=htmlspecialchars($c['email']??'')?></td><td><?=htmlspecialchars($c['telefone']??'')?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-warning" href="/?r=clientes&form=1&id=<?=$c['id']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este cliente?')"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn btn-sm btn-danger" name="excluir">Excluir</button></form></td></tr><?php endforeach; ?><?php if(!$clientes): ?><tr><td colspan="5">Nenhum cliente cadastrado.</td></tr><?php endif; ?></tbody></table></div>
